var n=`0522-chelo-kebab`;var o=`world-0522`;var t=`IR`;var r=`western-asia`;var a=4;var l=63;var s={en:`Chelo Kebab`,ua:`Чело-кебаб`};var d={en:`A traditional dish from Iran, centered on ground beef, ground lamb, yellow onion, basmati rice. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Іран. Основні складники: яловичий фарш, фарш з ягнятини, жовта цибуля, рис басматі. Домашній варіант із кількостями продуктів за етапами приготування.`};var u=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`ground-beef`,520,`g`],[`ground-lamb`,200,`g`],[`yellow-onion`,220,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`],[`sumac`,7,`g`]]},{en:`Thread the prepared pieces onto skewers, leaving small gaps to ensure even cooking.`,ua:`Нанизайте підготовлені шматочки на шампури чи шпажки, залишаючи невеликі проміжки для рівномірного приготування.`,t:[`threading-skewers`],m:12,i:[]},{en:`Grill over medium-high heat for about 16 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 16 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:16,i:[]},{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 25 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 25 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:25,i:[[`basmati-rice`,460,`g`],[`saffron-threads`,.3,`g`]]}];var g={slug:n,id:o,country:`IR`,region:r,servings:4,minutes:63,title:s,text:d,steps:u};export{t as country,g as default,o as id,l as minutes,r as region,a as servings,n as slug,u as steps,d as text,s as title};